(()=>{importScripts("/wasm_exec.js");var m=async()=>{let t=new Go,r=await WebAssembly.instantiateStreaming(fetch("/nes.wasm"),t.importObject);t.run(r.instance)};m();var f=new SharedArrayBuffer(256*240*4),w=new Uint8Array(f),n=8192,i=new SharedArrayBuffer(n*4+4+4+4),p=new Float32Array(i,0,n),s=new Int32Array(i,n*4,3),c=1024,u=new Float32Array(c);self.onmessage=async({data:t})=>{switch(t.type){case"init":startEmulator(),initBuffer(new Uint8Array(u.buffer)),initInput(new Int32Array(t.inputBuf)),self.postMessage({type:"init",audioBufS:i,FBuf:f,SIZE:n,S_size:c});break;case"loadRom":await l(t.rom),running=!0,y();break;case"input":update(t.action,t.pressed);break}};var y=()=>{for(;;){Atomics.wait(s,2,0);let t=Atomics.load(s,0),r=Atomics.load(s,1),a=n-(t-r),e=Math.min(a,c);if(e>0){drive(e);for(let o=0;o<e;o++)p[(t+o)%n]=u[o];Atomics.store(s,0,t+e)}w.set(new Uint8Array(frameBuffer.buffer)),self.postMessage({type:"frameUp"}),Atomics.store(s,2,0),Atomics.notify(s,2)}},l=async t=>{let a=await(await fetch("/games/"+t+".nes")).arrayBuffer(),e=new Uint8Array(a);initRom(e)};})();
